import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Organize automations","description":"","frontmatter":{"title":"Organize automations","docId":"user.automations.index","translationKey":"user.automations.index","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"08bb26a20687b58094e908a4e8395abeae3b9adc3932c86d9c3b08f5ebbf8ce3","translationRevision":"08bb26a20687b58094e908a4e8395abeae3b9adc3932c86d9c3b08f5ebbf8ce3","order":10},"headers":[],"relativePath":"en/user/automations/index.md","filePath":"en/user/automations/index.md","lastUpdated":1795727787000}`),s={name:`en/user/automations/index.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="organize-automations" tabindex="-1">Organize automations <a class="header-anchor" href="#organize-automations" aria-label="Permalink to “Organize automations”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Build a small, understandable library that responds to LIVE events. You need a working desktop host. A real <a href="./../live/connections.html">LIVE connection</a> is needed to validate upstream events; plugin actions also require their plugin and service to be ready.</p><h2 id="understand-the-library" tabindex="-1">Understand the library <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to “Understand the library”">​</a></h2><p>An <strong>Action</strong> is a reusable configured operation, such as writing a log line or playing a sound. An <strong>Event</strong> chooses a trigger, filters, cooldown and linked actions. A profile groups definitions for a workflow; only one profile pack is active at a time. Runtime <a href="./variables.html">Variables</a> supply values that several actions can reuse.</p><ol><li>Open <strong>Automations</strong> and confirm the active profile before editing. Search Events and Actions separately so you know which kind of record you are selecting.</li><li>Begin with the <a href="./first-rule.html">first logging rule</a>. Create its action, then an event that references it.</li><li>Choose a trigger supported by the current host. Use the field picker to add filters for that trigger. Multiple conditions narrow matching; they do not change the incoming payload.</li><li>Set a cooldown and its scope. A global cooldown limits the rule across viewers; a per-user cooldown tracks viewers separately.</li><li>Link the intended actions in order. The normal mode runs the chosen list; random mode selects an action from it. A delay action postpones later actions rather than slowing LIVE ingestion.</li><li>Save, review any displayed definition changes, then explicitly enable the records you intend to run. Check the run history for the action name, outcome and error.</li></ol><p>Every comparison can take a list of values instead of a single one. The default combines them as “any”: the condition passes when at least one value matches. Switch the quantifier to “all” when every value must match — for “is not” this reads “is none of”. A condition can also name a capture alias; the winning value is then available to action templates as <code>{{ match.&lt;alias&gt; }}</code> (or <code>{{ match.&lt;position&gt; }}</code> without an alias). Below the always-required conditions you can add up to four <strong>alternatives</strong>: groups whose conditions must all pass inside the group, where any single group is enough for the event to fire.</p><p>Tests can execute the configured effects. Read the selected action list before pressing <strong>Test</strong> or firing an event, especially for audio, HTTP, points and plugin operations. Use logging while learning.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Expected result and status”">​</a></h2><p>Local editing, execution, templates, profiles and history are available. Plugin triggers appear only while their supporting plugin is installed and enabled. Activation depends on the import surface and reviewed enabled values; inspect both events and actions before confirming. The Events/Actions <strong>Changes</strong> panel is a <a href="./../cloud/changes.html">local reference comparison</a>, not automatic Cloud upload.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recovery”">​</a></h2><p>For no run, check active profile, enabled states, trigger, filters, cooldown and missing actions in that order. For a revision conflict, read the current saved definition and review again. Do not overwrite another person&#39;s update blindly. Export a known-good <a href="./templates.html">profile</a> before broad changes.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Operational details”">​</a></h2><p>Before changing profiles or importing, read the <a href="./templates.html#operational-details">activation rules by surface</a>. Profile switching can enable members that you had individually disabled. Cooldown state is in memory, capped at 24 hours; missing viewer uniqueId shares one anonymous scope. The table clears when it reaches 8,192 retained keys, so overload or restart can allow extra runs. It is not a durable quota or replay guarantee.</p><p>Try it interactively before touching your real setup:</p>`,15),t(d,{scenario:`automation`,locale:`en`,panel:`automation`,title:`Try the automations workspace`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Command line operations <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Command line operations”">​</a></h2><p>Every operation in this guide is also available from the CLI — offline, scriptable and agent-friendly. Usage lines are parser syntax and stay in English in every locale.</p><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>list automation rules</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>template context available to rules</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>read one rule</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>create a rule</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>update a rule</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>delete a rule <strong>destructive</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>enable a rule</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>disable a rule</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>dry-run a rule against a sample event</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>fire a trigger manually</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>apply a moderation penalty in points</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>list saved workflow graphs</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>read one graph</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>create or replace a graph</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>delete a graph <strong>destructive</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>enable a graph</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>disable a graph</td></tr></tbody></table><p>See the <a href="./../../developer/cli.html">full command reference</a> for conventions, JSON output and destructive-operation markers.</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};